<script lang="ts">
 import {cameraMode,resetCamera} from './cameraViews';
 import {onMount} from 'svelte';
 import {preferences,settingsOpen,updatePreference,currentPreferences,ANIMATION_RATES} from './settings';
 import {tableAudio,audioState} from './audio/engine';
 let {lab=false}:{lab?:boolean}=$props();let dialog=$state<HTMLDialogElement>();
 $effect(()=>{tableAudio.apply($preferences);});
 $effect(()=>{if(!dialog)return;if($settingsOpen&&!dialog.open)dialog.showModal();else if(!$settingsOpen&&dialog.open)dialog.close();});
 onMount(()=>{
  const unlock=()=>void tableAudio.unlock(),visibility=()=>tableAudio.setVisible(document.visibilityState==='visible');
  const escape=(event:KeyboardEvent)=>{if(event.key==='Escape'&&$cameraMode)cameraMode.set(false);};
  document.addEventListener('keydown',escape);
  document.addEventListener('pointerdown',unlock,{capture:true});document.addEventListener('keydown',unlock,{capture:true});document.addEventListener('click',unlock,{capture:true});document.addEventListener('visibilitychange',visibility);
  return()=>{document.removeEventListener('keydown',escape);document.removeEventListener('pointerdown',unlock,true);document.removeEventListener('keydown',unlock,true);document.removeEventListener('click',unlock,true);document.removeEventListener('visibilitychange',visibility);tableAudio.destroy();};
 });
 function music(){updatePreference('music',!$preferences.music);tableAudio.apply(currentPreferences());void tableAudio.unlock();}
 function effects(){updatePreference('effects',!$preferences.effects);tableAudio.apply(currentPreferences());void tableAudio.unlock();}
</script>
<div data-settings data-auto-seconds={$preferences.autoSeconds??'manual'} data-animation-rate={ANIMATION_RATES[$preferences.animationSpeed]} data-music-state={$audioState.music} data-audio-context={$audioState.context} data-effects-enabled={$preferences.effects} data-effects-played={$audioState.effects}>
 {#if !$cameraMode}<button class="settings-button" class:lab aria-label="Settings" title="Settings" onclick={()=>settingsOpen.set(true)}><span aria-hidden="true">⚙&#xfe0e;</span></button>{/if}
 {#if $cameraMode}<section class="camera-tools" aria-label="Set Camera" data-e2e-fit><span>Drag to turn · Pinch or scroll to zoom</span><div><button onclick={resetCamera}>Reset View</button><button class="done" onclick={()=>cameraMode.set(false)}>Done</button></div></section>{/if}
 <dialog bind:this={dialog} aria-labelledby="settings-title" onclose={()=>settingsOpen.set(false)} onclick={event=>{if(event.target===dialog)settingsOpen.set(false);}}>
  <section class="panel" data-e2e-fit>
   <header><h1 id="settings-title">Table settings</h1><button class="close" aria-label="Close settings" onclick={()=>settingsOpen.set(false)}>×</button></header>
   <div class="setting"><label for="auto-play">Auto-play</label><select id="auto-play" value={$preferences.autoSeconds??'manual'} onchange={e=>updatePreference('autoSeconds',e.currentTarget.value==='manual'?null:Number(e.currentTarget.value))}><option value="manual">∞ · Manual</option>{#each [5,4,3,2,1,0] as seconds}<option value={seconds}>{seconds} {seconds===1?'second':'seconds'}</option>{/each}</select><p>Cut, Go, Peg, Deal and the only playable card.</p></div>
   <div class="setting"><label for="animation-speed">Animation</label><select id="animation-speed" value={$preferences.animationSpeed} onchange={e=>updatePreference('animationSpeed',e.currentTarget.value as 'standard'|'fast'|'ultra')}><option value="standard">Standard</option><option value="fast">Fast</option><option value="ultra">Ultra</option></select></div>
   <div class="setting camera-setting"><span>Camera</span><button onclick={()=>{settingsOpen.set(false);cameraMode.set(true);}}>Set Camera</button></div>
   <div class="sound-setting"><div class="switch-row"><span id="music-label">Chamber music</span><button class="switch" role="switch" aria-labelledby="music-label" aria-checked={$preferences.music} onclick={music}><i></i></button></div><p class="piece">Baize at Dusk <span>· flute and strings</span></p><label class="volume" for="music-volume">Volume <output>{Math.round($preferences.musicVolume*100)}%</output></label><input id="music-volume" aria-label="Music volume" type="range" min="0" max="100" step="5" value={$preferences.musicVolume*100} oninput={e=>updatePreference('musicVolume',Number(e.currentTarget.value)/100)}/>
    {#if $preferences.music&&$audioState.music==='waiting'}<p class="audio-note">Music begins with your next tap.</p>{:else if $preferences.music&&$audioState.music==='loading'}<p class="audio-note">Loading music…</p>{:else if $preferences.music&&$audioState.music==='error'}<button class="retry" onclick={()=>void tableAudio.unlock()}>Try music again</button>{/if}
    <a class="score" href={`${import.meta.env.BASE_URL}music/baize-at-dusk.musicxml`} download>Score</a>
   </div>
   <div class="sound-setting"><div class="switch-row"><span id="effects-label">Sound effects</span><button class="switch" role="switch" aria-labelledby="effects-label" aria-checked={$preferences.effects} onclick={effects}><i></i></button></div><label class="volume" for="effects-volume">Volume <output>{Math.round($preferences.effectsVolume*100)}%</output></label><input id="effects-volume" aria-label="Effects volume" type="range" min="0" max="100" step="5" value={$preferences.effectsVolume*100} oninput={e=>updatePreference('effectsVolume',Number(e.currentTarget.value)/100)}/></div>
  </section>
 </dialog>
</div>
<style>
 .camera-setting button,.camera-tools button{font:16px Georgia,serif;min-height:44px;padding:10px 16px;color:#eedfbf;background:#213b30;border:1px solid #a68b5866;border-radius:3px;cursor:pointer}.camera-tools{position:fixed;bottom:18px;left:50%;transform:translateX(-50%);z-index:4;max-width:calc(100vw - 24px);padding:10px 16px;border:1px solid #bda16b;border-radius:6px;background:#172d24ed;color:#eddfbd;box-shadow:0 4px 24px #0006;text-align:center;font:14px Georgia,serif}.camera-tools span{display:block;margin-bottom:8px;white-space:nowrap}.camera-tools div{display:flex;justify-content:center;gap:10px}.camera-tools .done{background:#c8af78;color:#19241b}
 .settings-button{position:fixed;top:20px;right:22px;z-index:3;width:44px;height:44px;padding:0;border:1px solid #b89b6170;border-radius:50%;color:#d9c695;background:#10291ed9;box-shadow:0 2px 8px #0005;font:27px Georgia,serif;cursor:pointer}.settings-button.lab{top:2px;right:114px;width:44px;height:44px;font-size:24px}.settings-button:hover{background:#284133;color:#f5dfac}.settings-button:focus-visible,button:focus-visible,select:focus-visible,input:focus-visible,a:focus-visible{outline:2px solid #e4c585;outline-offset:3px}dialog{padding:0;border:1px solid #bda16b;border-radius:8px;color:#eddfbd;background:#172d24;box-shadow:0 24px 100px #000b;max-width:calc(100vw - 32px);max-height:calc(100svh - 32px);font:17px Georgia,serif}dialog::backdrop{background:#06100c99;backdrop-filter:blur(3px)}.panel{width:410px;max-width:100%;padding:25px 30px;background:linear-gradient(120deg,#183026,#11251f)}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}h1{font-size:27px;font-weight:400;letter-spacing:.5px;margin:0}.close{font:30px Georgia,serif;background:transparent;border:0;color:#d9c695;width:44px;height:44px;cursor:pointer}.setting{display:grid;grid-template-columns:1fr 164px;align-items:center;gap:10px;margin:18px 0}.setting p{grid-column:1/-1;font-size:13px;color:#adb9a5;margin:0;line-height:1.5}select{font:16px Georgia,serif;color:#eedfbf;background:#213b30;border:1px solid #a68b5866;border-radius:3px;padding:10px;min-height:44px;width:100%}.sound-setting{border-top:1px solid #aa91553b;margin-top:23px;padding-top:21px}.switch-row{display:flex;align-items:center;justify-content:space-between}.switch{position:relative;width:48px;height:44px;border:0;background:transparent;padding:12px 4px;cursor:pointer}.switch::before{content:"";position:absolute;inset:8px 0;border:1px solid #9a8c6266;border-radius:15px;background:#0b1c16}.switch i{position:relative;display:block;width:20px;height:20px;border-radius:50%;background:#7f907d;transition:transform .12s,background .12s}.switch[aria-checked=true]::before{background:#6d603e}.switch[aria-checked=true] i{transform:translateX(19px);background:#e5d1a0}.piece{color:#d1bd8b;font-style:italic;font-size:15px;margin:11px 0 17px}.piece span{color:#aab5a1;font-size:12px}.volume{display:flex;justify-content:space-between;font-size:13px;color:#afbaa5;margin-top:15px}input[type=range]{display:block;width:100%;height:25px;margin:7px 0 0;accent-color:#d1b77d;cursor:pointer}.score,.retry{color:#c6b181;font:13px Georgia,serif}.score{display:inline-block;margin-top:7px}.audio-note{font-size:12px;color:#b8c3ac;margin:6px 0}.retry{background:none;border:0;padding:5px 0;text-decoration:underline;cursor:pointer}
</style>
